        const kind = setKind(a);
        const sc = new Map(ancs.map(an => [an, plan.bias(kind, { x: an.x, z: an.z, face: an.face || (an.faces && an.faces[0]), t: an.t, corner: an.anchor === 'corner', win: an.anchor === 'window', yaw: an.yaw }) + R2() * 1.5]));
