    if (R() > 0.3 + 0.7 * P.clutter) continue;
    if (!sp.rug && bears(p)) continue;
    p._sp = sp;
    const before = problems(p);
    const old = { x: p.x, z: p.z, yaw: p.yaw, q: p.q };
    const dr = (R() * 2 - 1) * sp.rot * amp, dx = (R() * 2 - 1) * sp.off * amp, dz = (R() * 2 - 1) * sp.off * amp;
    let ok = false;
