  fam.roof = C.roof === 'flat' || flatOnly ? 'flat' : pick(FR, C.roofs || ROOF_BY_CULTURE[cultureKey] || { gable: 1 });
  if (T.open === 'sides' && FR() < 0.4) fam.roof = 'shed';
