    if (o.flue && all.some(c => inRect(o.flue, c[0], c[1], 1.6))) continue; // the fire and its ring stay clear of the flight
    if ([o.door, o.back].some(d => d && all.slice(0, -1).some(c => near(c, d)))) continue;
