  hall: { use: 'hall', type: 'longhouse', fire: true },
  tavern: { use: 'hall', type: 'tavern', fire: true },
  kitchen: { use: 'home', type: 'home', role: 'kitchen' },
  smithy: { use: 'smithy', type: 'smithy' },
  workshop: { use: 'workshop', type: 'workshop' },
