  const hung = furniture.filter(p => { const f = F[p.name] || {}; return f.at === 'mount' || (p.name === 'itemstandh' && p.y > 0.6 && !furniture.some(t => (F[t.name] || {}).cat === 'table' && Math.hypot(t.x - p.x, t.z - p.z) < 2.2 && Math.abs(t.y + 0.75 - p.y) < 0.2)); });
