    const d = Math.abs((p.x - o.x) * ax + (p.z - o.z) * az);
    const r = Math.abs((p.c * ax + -p.s * az)) * p.hw + Math.abs((p.s * ax + p.c * az)) * p.hd;
    best = Math.max(best, d - h - r);
